/* eslint-disable @typescript-eslint/no-explicit-any */
'use client';
import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardContent,
  Divider,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Button,
  Tooltip,
  CircularProgress,
  useTheme,
  useMediaQuery,
  Chip,
  IconButton,
  Alert,
  Snackbar,
} from '@mui/material';
import { BarChart } from '@mui/x-charts/BarChart';
import { Gauge } from '@mui/x-charts/Gauge';
import RefreshIcon from '@mui/icons-material/Refresh';
import SettingsIcon from '@mui/icons-material/Settings';
import FullscreenIcon from '@mui/icons-material/Fullscreen';
import DownloadIcon from '@mui/icons-material/Download';
import { Area, AreaChart, ResponsiveContainer, XAxis, YAxis, Tooltip as RechartsTooltip } from 'recharts';
import axios from 'axios';

// Type definitions for better type safety
interface SalesData {
  date: string;
  value: number;
}

interface RevenueData {
  date: string;
  value: number;
}

interface GaugeData {
  label: string;
  value: number;
  color: string;
}

const RealTimeInsights: React.FC = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  
  // State management
  const [timeRange, setTimeRange] = useState('monthly');
  const [sales, setSales] = useState<SalesData[]>([]);
  const [revenue, setRevenue] = useState<RevenueData[]>([]);
  const [gaugeData, setGaugeData] = useState<GaugeData[]>([]);
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  // Fetch data from real API
  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // Replace with your actual API endpoint
      const salesResponse = await axios.get(`https://api.example.com/sales?timeRange=${timeRange}`);
      const revenueResponse = await axios.get(`https://api.example.com/revenue?timeRange=${timeRange}`);
      const metricsResponse = await axios.get('https://api.example.com/metrics');
      
      // For demonstration purposes, fallback to simulated data if API call fails
      setSales(salesResponse.data || generateSimulatedSalesData());
      setRevenue(revenueResponse.data || generateSimulatedRevenueData());
      setGaugeData(metricsResponse.data || generateSimulatedGaugeData());
      
      setLastUpdated(new Date());
    } catch (error) {
      console.error('Error fetching data:', error);
      setError('Failed to fetch data. Using simulated data instead.');
      
      // Fallback to simulated data
      setSales(generateSimulatedSalesData());
      setRevenue(generateSimulatedRevenueData());
      setGaugeData(generateSimulatedGaugeData());
      setLastUpdated(new Date());
    } finally {
      setLoading(false);
    }
  };
  
  // Generate simulated data (fallback)
  const generateSimulatedSalesData = (): SalesData[] => {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return Array.from({ length: 12 }, (_, i) => ({
      date: months[i],
      value: Math.floor(Math.random() * 800) + 200,
    }));
  };
  
  const generateSimulatedRevenueData = (): RevenueData[] => {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return Array.from({ length: 12 }, (_, i) => ({
      date: months[i],
      value: Math.floor(Math.random() * 4000) + 1000,
    }));
  };
  
  const generateSimulatedGaugeData = (): GaugeData[] => {
    return [
      { label: 'Sales Target', value: Math.floor(Math.random() * 40) + 60, color: theme.palette.primary.main },
      { label: 'Revenue Growth', value: Math.floor(Math.random() * 30) + 40, color: theme.palette.secondary.main },
      { label: 'Active Users', value: Math.floor(Math.random() * 25) + 65, color: '#4caf50' },
      { label: 'Customer Satisfaction', value: Math.floor(Math.random() * 15) + 80, color: '#9c27b0' }
    ];
  };
  
  // Initial data fetch and polling setup
  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000); // Fetch data every 30 seconds
    return () => clearInterval(interval);
  }, [timeRange]);
  
  // Handle manual refresh
  const handleRefresh = () => {
    fetchData();
  };
  
  // Export data to CSV
  const exportToCSV = () => {
    const salesCSV = sales.map(item => `${item.date},${item.value}`).join('\n');
    const blob = new Blob([`Date,Sales\n${salesCSV}`], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.setAttribute('hidden', '');
    a.setAttribute('href', url);
    a.setAttribute('download', `sales_data_${timeRange}.csv`);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <Box sx={{ 
      p: { xs: 2, md: 4 }, 
      backgroundColor: theme.palette.background.default, 
      minHeight: '100vh',
      borderRadius: 2,
      transition: 'all 0.3s ease'
    }}>
      {/* Header Section with improved layout */}
      <Box sx={{ 
        display: 'flex', 
        flexDirection: isMobile ? 'column' : 'row',
        justifyContent: 'space-between', 
        alignItems: isMobile ? 'flex-start' : 'center', 
        mb: 4,
        gap: 2
      }}>
        <Box>
          <Typography variant="h4" sx={{ 
            fontWeight: 700, 
            color: theme.palette.primary.main,
            mb: 1
          }}>
            Real-Time Insights
          </Typography>
          <Chip 
            label={`Environment: ${process.env.NODE_ENV === 'production' ? 'Production' : 'Development'}`}
            color="info"
            size="small"
            sx={{ mr: 1 }}
          />
          <Chip 
            label={`Status: ${error ? 'Simulated Data' : 'Live Data'}`}
            color={error ? 'warning' : 'success'}
            size="small"
          />
        </Box>
        
        <Box sx={{ 
          display: 'flex', 
          alignItems: 'center',
          flexWrap: isMobile ? 'wrap' : 'nowrap',
          gap: 1
        }}>
          <FormControl size="small" sx={{ minWidth: 150 }}>
            <InputLabel id="time-range-label">Time Range</InputLabel>
            <Select
              labelId="time-range-label"
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              sx={{ 
                backgroundColor: theme.palette.background.paper,
                borderRadius: 2
              }}
            >
              <MenuItem value="daily">Daily</MenuItem>
              <MenuItem value="weekly">Weekly</MenuItem>
              <MenuItem value="monthly">Monthly</MenuItem>
              <MenuItem value="quarterly">Quarterly</MenuItem>
              <MenuItem value="yearly">Yearly</MenuItem>
            </Select>
          </FormControl>
          
          <IconButton onClick={exportToCSV} color="primary" size="small" sx={{ ml: 1 }}>
            <DownloadIcon />
          </IconButton>
          
          <Tooltip title="Refresh Data">
            <Button
              variant="contained"
              startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <RefreshIcon />}
              onClick={handleRefresh}
              disabled={loading}
              sx={{ 
                borderRadius: 2,
                textTransform: 'none',
                ml: 1
              }}
            >
              {loading ? 'Loading...' : 'Refresh'}
            </Button>
          </Tooltip>
        </Box>
      </Box>

      {/* Error notification */}
      <Snackbar open={!!error} autoHideDuration={6000}>
        <Alert severity="warning" variant="filled">
          {error}
        </Alert>
      </Snackbar>

      {/* Last Updated with improved styling */}
      <Typography 
        variant="body2" 
        color="text.secondary" 
        align="right" 
        sx={{ 
          mb: 3,
          fontStyle: 'italic',
          display: 'flex',
          justifyContent: 'flex-end',
          alignItems: 'center'
        }}
      >
        <RefreshIcon sx={{ fontSize: 16, mr: 0.5 }} />
        Last updated: {lastUpdated.toLocaleTimeString()} - {lastUpdated.toLocaleDateString()}
      </Typography>

      {/* Main Insights Section with improved card design */}
      <Grid container spacing={3}>
        {/* Monthly Sales Card */}
        <Grid item xs={12} md={6}>
          <Card sx={{
            borderRadius: 3,
            boxShadow: '0 8px 16px rgba(0,0,0,0.1)',
            overflow: 'hidden',
            transition: 'transform 0.3s, box-shadow 0.3s',
            '&:hover': { 
              transform: 'translateY(-5px)',
              boxShadow: '0 12px 20px rgba(0,0,0,0.15)'
            },
            height: '100%'
          }}>
            <CardContent sx={{ p: 0 }}>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                p: 2,
                backgroundColor: theme.palette.primary.main + '10' 
              }}>
                <Typography variant="h6" sx={{ fontWeight: 600, color: theme.palette.primary.main }}>
                  Sales Trend {timeRange === 'monthly' ? '(Monthly)' : `(${timeRange})`}
                </Typography>
                <Box>
                  <IconButton size="small">
                    <SettingsIcon fontSize="small" />
                  </IconButton>
                  <IconButton size="small">
                    <FullscreenIcon fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
              <Divider />
              <Box sx={{ p: 1, height: 320 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sales} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                    <XAxis dataKey="date" />
                    <YAxis />
                    <RechartsTooltip 
                      formatter={(value) => [`$${value}`, 'Sales']}
                      labelFormatter={(label) => `Date: ${label}`}
                    />
                    <Area 
                      type="monotone" 
                      dataKey="value" 
                      stroke={theme.palette.primary.main} 
                      fill={theme.palette.primary.main + '40'}
                      strokeWidth={2}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Monthly Revenue Card */}
        <Grid item xs={12} md={6}>
          <Card sx={{
            borderRadius: 3,
            boxShadow: '0 8px 16px rgba(0,0,0,0.1)',
            overflow: 'hidden',
            transition: 'transform 0.3s, box-shadow 0.3s',
            '&:hover': { 
              transform: 'translateY(-5px)',
              boxShadow: '0 12px 20px rgba(0,0,0,0.15)'
            },
            height: '100%'
          }}>
            <CardContent sx={{ p: 0 }}>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                p: 2,
                backgroundColor: theme.palette.secondary.main + '10' 
              }}>
                <Typography variant="h6" sx={{ fontWeight: 600, color: theme.palette.secondary.main }}>
                  Revenue {timeRange === 'monthly' ? '(Monthly)' : `(${timeRange})`}
                </Typography>
                <Box>
                  <IconButton size="small">
                    <SettingsIcon fontSize="small" />
                  </IconButton>
                  <IconButton size="small">
                    <FullscreenIcon fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
              <Divider />
              <Box sx={{ p: 2, height: 320, display: 'flex', justifyContent: 'center' }}>
                <BarChart
                  xAxis={[{ 
                    data: revenue.map(d => d.date), 
                    scaleType: 'band',
                    tickLabelStyle: {
                      fontSize: 12
                    }
                  }]}
                  series={[{ 
                    data: revenue.map(d => d.value), 
                    color: theme.palette.secondary.main,
                    valueFormatter: (value) => `$${value.toLocaleString()}`
                  }]}
                  height={300}
                  width={isMobile ? 300 : 450}
                  margin={{ top: 20, right: 30, left: 20, bottom: 20 }}
                />
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Key Performance Indicators */}
        <Grid item xs={12}>
          <Card sx={{
            borderRadius: 3,
            boxShadow: '0 8px 16px rgba(0,0,0,0.1)',
            transition: 'transform 0.3s, box-shadow 0.3s',
            '&:hover': { 
              transform: 'translateY(-5px)',
              boxShadow: '0 12px 20px rgba(0,0,0,0.15)'
            }
          }}>
            <CardContent sx={{ p: 0 }}>
              <Box sx={{ p: 2, backgroundColor: 'rgba(0,0,0,0.02)' }}>
                <Typography variant="h6" sx={{ fontWeight: 600 }}>
                  Key Performance Indicators
                </Typography>
              </Box>
              <Divider />
              <Box sx={{ 
                p: 3, 
                display: 'flex', 
                flexWrap: 'wrap',
                justifyContent: 'space-around',
                alignItems: 'center',
                gap: 3
              }}>
                {gaugeData.map((gauge, index) => (
                  <Box key={index} sx={{ 
                    textAlign: 'center',
                    transition: 'transform 0.2s',
                    '&:hover': { transform: 'scale(1.05)' }
                  }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 500, mb: 1 }}>
                      {gauge.label}
                    </Typography>
                    <Gauge
                      series={[
                        {
                          data: [{ value: gauge.value }],
                          color: gauge.color,
                          arcLabel: (item) => `${item.value}%`,
                        },
                      ]}
                      width={140}
                      height={140}
                      cornerRadius={6}
                      startAngle={-150}
                      endAngle={150}
                      sx={{ my: 1 }}
                    />
                    <Typography 
                      variant="body2" 
                      sx={{ 
                        color: gauge.value > 70 ? 'success.main' : gauge.value > 50 ? 'warning.main' : 'error.main',
                        fontWeight: 'bold'
                      }}
                    >
                      {gauge.value >= 70 ? 'Good' : gauge.value >= 50 ? 'Average' : 'Needs Improvement'}
                    </Typography>
                  </Box>
                ))}
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default RealTimeInsights;